import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowLeft, faDownload, faTrash } from "@fortawesome/free-solid-svg-icons";

function PlaygroundResults() {
  const navigate = useNavigate();
  const [currentResult, setCurrentResult] = useState(null);
  const [allResults, setAllResults] = useState([]);
  const [showDetailedView, setShowDetailedView] = useState(false);

  useEffect(() => {
    const examResult = localStorage.getItem("examResult");
    if (examResult) {
      setCurrentResult(JSON.parse(examResult));
    }

    const results = JSON.parse(localStorage.getItem("allExamResults") || "[]");
    setAllResults(results);
  }, []);

  const handleBack = () => navigate("/dashboard/playground");

  const handleDownload = (result) => {
    if (!result) return alert("No result data");

    const passed = result.correctAnswers * 2 >= 20;
    const studentName =
      result.user?.firstName || result.user?.username || "Unknown";

    const content = `
Student: ${studentName}
Score: ${result.correctAnswers * 2}/40
Status: ${passed ? "Pass" : "Fail"}
    `.trim();

    const blob = new Blob([content], { type: "text/plain;charset=utf-8" });
    const url = window.URL.createObjectURL(blob);

    const a = document.createElement("a");
    a.href = url;
    a.download = `result-${studentName}.txt`;
    a.click();

    window.URL.revokeObjectURL(url);
  };

  const handleDelete = (examDate) => {
    if (!window.confirm("Delete this result?")) return;

    const updated = allResults.filter((r) => r.examDate !== examDate);
    setAllResults(updated);
    localStorage.setItem("allExamResults", JSON.stringify(updated));

    if (currentResult?.examDate === examDate) {
      setCurrentResult(null);
      localStorage.removeItem("examResult");
    }
  };

  const handleViewDetails = (result) => {
    setCurrentResult(result);
    setShowDetailedView(true);
  };

  if (!currentResult) {
    return <h2>No Results Found</h2>;
  }

  const passed = currentResult.correctAnswers * 2 >= 20;

  return (
    <div style={{ padding: "20px" }}>
      <div className="max-w-6xl mx-auto">

        {/* HEADER */}
        <div className="bg-white p-4 mb-4 shadow rounded flex justify-between">
          <button onClick={handleBack}>
            <FontAwesomeIcon icon={faArrowLeft} /> Back
          </button>

          <div>
            <button onClick={() => handleDownload(currentResult)}>
              <FontAwesomeIcon icon={faDownload} />
            </button>

            <button onClick={() => handleDelete(currentResult.examDate)}>
              <FontAwesomeIcon icon={faTrash} />
            </button>
          </div>
        </div>

        {/* SHOW DETAILS */}
        {showDetailedView && (
          <>
            <div className="grid grid-cols-4 gap-4 mb-4">
              <div>Score: {currentResult.correctAnswers * 2}/40</div>
              <div>Status: {passed ? "Pass" : "Fail"}</div>
            </div>

            <button onClick={() => setShowDetailedView(false)}>
              Close Details
            </button>
          </>
        )}

        {/* ALL RESULTS */}
        <div className="bg-white p-4 shadow rounded">
          <h3>All Results</h3>

          <table className="w-full mt-3">
            <thead>
              <tr>
                <th>S.No</th>
                <th>Name</th>
                <th>Score</th>
                <th>Actions</th>
              </tr>
            </thead>

            <tbody>
              {allResults.map((result, index) => (
                <tr key={index}>
                  <td>{index + 1}</td>
                  <td>
                    {result.user?.firstName ||
                      result.user?.username ||
                      "Unknown"}
                  </td>
                  <td>{result.correctAnswers * 2}/40</td>

                  <td>
                    <button onClick={() => handleViewDetails(result)}>≡ƒæü</button>
                    <button onClick={() => handleDownload(result)}>≡ƒôÑ</button>
                    <button onClick={() => handleDelete(result.examDate)}>≡ƒùæ</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

      </div>
    </div>
  );
}

export default PlaygroundResults;

import { Routes, Route, Navigate, useLocation } from "react-router-dom";
import { useEffect } from "react";
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import Dashboard from "./Layout/Dashboard";
import Dashboardsssit from "./pages/Dashboardsssit";   // Γ£à ADD THIS

import Jobs from "./pages/Jobs";
import AllJobs from "./pages/Alljobs";
import JobDetails from "./pages/jobDetails";
import AppliedJobs from "./pages/AppliedJobs";

import ExamReports from "./pages/ExamReports";
import DailyExamReports from "./pages/DailyExamReports";
import WeeklyExamReports from "./pages/WeeklyExamReports";
import MonthlyExamReports from "./pages/MonthlyExamReports";
import ExamReportDetail from "./pages/ExamReportDetail";
import ExamLeaderboard from "./pages/ExamLeaderboard";
import Exams from "./pages/Exams";

import Logout from "./pages/Logout";
import Login from "./pages/Login";
import Profile from "./pages/Profile";
import PythonExam from "./pages/PythonExam";

import Playground from "./pages/Playground";
import PlaygroundDetail from "./pages/PlaygroundDetail";
import PlaygroundResults from "./pages/PlaygroundResults";
import DetailedResults from "./pages/DetailedResults";

import LeaveRequest from "./pages/Leaverequest";
import Course from "./pages/Course";
import TopicVideo from "./pages/TopicVideo";
import VideoPlayer from "./pages/VideoPlayer";

function App() {
  const isLoggedIn = localStorage.getItem("access");
  const location = useLocation();

  // Disable browser back button globally
  useEffect(() => {
    if (window.allowBrowserBack) {
      return;
    }

    window.history.pushState(null, null, window.location.pathname + window.location.search);

    const handlePopState = (event) => {
      if (window.allowBrowserBack) {
        return;
      }
      window.history.pushState(null, null, window.location.pathname + window.location.search);
    };

    window.addEventListener("popstate", handlePopState);

    return () => {
      window.removeEventListener("popstate", handlePopState);
    };
  }, [location]);

  return (
    <>
      <ToastContainer position="top-right" autoClose={2000} />

      <Routes>

        {/* Login */}
        <Route path="/" element={<Login />} />

        {/* ≡ƒöÑ SSSIT Landing Dashboard */}
        <Route path="/dashboardsssit" element={<Dashboardsssit />} />


        {/* Video Player (Standalone) */}
        <Route path="/video/:courseTitle/:topicName" element={<VideoPlayer />} />

        {/* Detailed Results (No Sidebar) */}

        {/* Standalone */}
        <Route path="/exam" element={<Exams />} />

        <Route path="/detailed-results/:index" element={<DetailedResults />} />

        {/* Exams (Fullscreen, No Sidebar/Navbar) */}
        <Route path="/dashboard/python-exam" element={<PythonExam />} />

        {/* ≡ƒöÉ Protected Dashboard */}
        <Route
          path="/dashboard"
          element={
            isLoggedIn ? <Dashboard /> : <Navigate to="/" />
          }
        >

          {/* Default */}
          <Route index element={<Profile />} />

          {/* Profile */}
          <Route path="profile" element={<Profile />} />

          {/* Courses */}
          <Route path="course" element={<Course />} />
          <Route path="course/:courseId" element={<Course />} />
          <Route path="course/video/:courseId/:topicId" element={<TopicVideo />} />

          {/* Jobs */}
          <Route path="jobs" element={<Jobs />} />
          <Route path="alljobs" element={<AllJobs />} />
          <Route path="appliedjobs" element={<AppliedJobs />} />
          <Route path="applied" element={<AppliedJobs />} />
          <Route path="jobs/:id" element={<JobDetails />} />

          {/* Exams */}
          <Route path="exams" element={<Exams />} />
          <Route path="exam-reports" element={<ExamReports />} />
          <Route path="reports" element={<ExamReports />} />
          <Route path="daily-exams" element={<DailyExamReports />} />
          <Route path="weekly-exams" element={<WeeklyExamReports />} />
          <Route path="monthly-exams" element={<MonthlyExamReports />} />
          <Route path="exam-leaderboard" element={<ExamLeaderboard />} />
          <Route path="leaderboard" element={<ExamLeaderboard />} />
          <Route path="exam-report-detail/:id" element={<ExamReportDetail />} />

          {/* Playground */}
          <Route path="playground" element={<Playground />} />
          <Route path="techlab" element={<Playground />} />
          <Route path="playground/:language" element={<PlaygroundDetail />} />
          <Route path="playground-results" element={<PlaygroundResults />} />
          <Route path="results" element={<PlaygroundResults />} />
          <Route path="playground/detailed-results/:index" element={<DetailedResults />} />

          {/* Leave */}
          <Route path="leave-request" element={<LeaveRequest />} />
          <Route path="leave" element={<LeaveRequest />} />

          {/* Logout */}
          <Route path="logout" element={<Logout />} />

        </Route>

      </Routes>
    </>
  );
}

export default App;

