import { Canvas, useFrame } from "@react-three/fiber";
import { Points, PointMaterial, Stars } from "@react-three/drei";
import { useRef, useMemo } from "react";
import * as THREE from "three";

function Dots() {
  const ref = useRef();

  const points = useMemo(() => {
    const positions = [];

    for (let i = 0; i < 2000; i++) {
      const r = 2.5;
      const theta = Math.random() * 2 * Math.PI;
      const phi = Math.acos(2 * Math.random() - 1);

      const x = r * Math.sin(phi) * Math.cos(theta);
      const y = r * Math.sin(phi) * Math.sin(theta);
      const z = r * Math.cos(phi);

      positions.push(x, y, z);
    }

    return new Float32Array(positions);
  }, []);

  useFrame(() => {
    ref.current.rotation.y += 0.0015;
  });

  return (
    <Points ref={ref} positions={points} stride={3}>
      <PointMaterial
        color="#00ff88"
        size={0.03}
        sizeAttenuation
        depthWrite={false}
      />
    </Points>
  );
}

export default function Globe() {
  return (
    <div className="absolute inset-0 flex items-center justify-center scale-150 opacity-70">
      <Canvas camera={{ position: [0, 0, 6] }}>
        <ambientLight intensity={0.5} />
        <Dots />
        <Stars radius={100} depth={50} count={3000} factor={4} />
      </Canvas>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { FaEye, FaArrowLeft, FaArrowRight } from "react-icons/fa";

function AllJobs() {
  const navigate = useNavigate();

  const [jobsData, setJobsData] = useState([]);
  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);
  const [search, setSearch] = useState("");

  // ==============================
  // APPLY JOB
  // ==============================
  function applyJob(jobId) {
    const token = localStorage.getItem("access");

    fetch("http://127.0.0.1:8000/api/applied-jobs/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ job: jobId }),
    })
      .then((res) =>
        res.json().then((data) => ({ status: res.status, data }))
      )
      .then(({ status }) => {
        if (status === 201) {
          alert("Applied Successfully Γ£à");

          setJobsData((prev) =>
            prev.map((job) =>
              job.id === jobId ? { ...job, status: "Applied" } : job
            )
          );
        } else {
          alert("Already Applied ΓÜá∩╕Å");
        }
      })
      .catch(() => alert("Error Γ¥î"));
  }

  // ==============================
  // FETCH JOBS + APPLIED STATUS
  // ==============================
  useEffect(() => {
    const token = localStorage.getItem("access");

    async function fetchData() {
      try {
        const jobsRes = await fetch(
          "http://127.0.0.1:8000/api/jobs/",
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        const jobs = await jobsRes.json();

        const appliedRes = await fetch(
          "http://127.0.0.1:8000/api/applied-jobs/",
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        const appliedJobs = await appliedRes.json();
        const appliedIds = appliedJobs.map((a) => a.job);

        const updated = jobs.map((j) => ({
          ...j,
          status: appliedIds.includes(j.id) ? "Applied" : j.status,
        }));

        setJobsData(updated);
      } catch (err) {
        console.log(err);
      }
    }

    fetchData();
  }, []);

  // ==============================
  // SEARCH
  // ==============================
  const filteredJobs = jobsData.filter((job) =>
    job.company?.toLowerCase().includes(search.toLowerCase()) ||
    job.job_title?.toLowerCase().includes(search.toLowerCase()) ||
    job.primary_skills?.toLowerCase().includes(search.toLowerCase())
  );

  // ==============================
  // PAGINATION
  // ==============================
  const totalPages = Math.ceil(filteredJobs.length / perPage);
  const records = filteredJobs.slice(
    (page - 1) * perPage,
    page * perPage
  );

  // ==============================
  // UI
  // ==============================
  return (
    <div className="container mt-4">
      <h4>All Job Openings</h4>

      <input
        className="form-control mb-3"
        placeholder="Search..."
        value={search}
        onChange={(e) => {
          setSearch(e.target.value);
          setPage(1);
        }}
      />

      <table className="table table-bordered">
        <thead>
          <tr>
            <th>Company</th>
            <th>Job Title</th>
            <th>Skills</th>
            <th>Deadline</th>
            <th>Location</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>

        <tbody>
          {records.length === 0 ? (
            <tr>
              <td colSpan="7" className="text-center">
                No Jobs
              </td>
            </tr>
          ) : (
            records.map((job) => (
              <tr key={job.id}>
                <td>{job.company}</td>
                <td>{job.job_title}</td>
                <td>{job.primary_skills}</td>
                <td>{job.deadline}</td>
                <td>{job.location}</td>

                <td>
                  {job.status === "Applied" ? (
                    <span className="badge bg-success">Applied</span>
                  ) : job.status === "Closed" ? (
                    <span className="badge bg-secondary">Closed</span>
                  ) : (
                    <span className="badge bg-primary">Open</span>
                  )}
                </td>

                <td>
                  <button
                    className="btn btn-sm btn-primary me-2"
                    onClick={() =>
                      navigate(`/dashboard/jobs/${job.id}`)
                    }
                  >
                    <FaEye />
                  </button>

                  {job.status === "Applied" ? (
                    <button className="btn btn-secondary btn-sm" disabled>
                      Applied
                    </button>
                  ) : (
                    <button
                      className="btn btn-success btn-sm"
                      onClick={() => applyJob(job.id)}
                    >
                      Apply
                    </button>
                  )}
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="d-flex justify-content-between">
        <button
          disabled={page === 1}
          onClick={() => setPage(page - 1)}
        >
          <FaArrowLeft />
        </button>

        <span>
          Page {page} / {totalPages || 1}
        </span>

        <button
          disabled={page === totalPages}
          onClick={() => setPage(page + 1)}
        >
          <FaArrowRight />
        </button>
      </div>
    </div>
  );
}

export default AllJobs;

