import React, { useState, useEffect } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowLeft, faDownload } from "@fortawesome/free-solid-svg-icons";
import jsPDF from 'jspdf';

function DetailedResults() {

  const navigate = useNavigate();
  const { index } = useParams();

  const [result, setResult] = useState(null);

  useEffect(() => {

    const results = JSON.parse(
      localStorage.getItem("allExamResults") || "[]"
    );

    if (results[index]) {
      setResult(results[index]);
    } else {
      console.error("DetailedResults - No result found at index:", index);
    }

  }, [index]);

  const handleBack = () => {
    navigate("/dashboard/playground-results");
  };

  const handleDownload = () => {
    if (!result) {
      alert("No result data available for download.");
      return;
    }

    const passed = (result.correctAnswers * 2) >= 20;
    const studentName = result.user?.firstName || result.user?.username || "Unknown";
    const examDate = result.examDate ? new Date(result.examDate).toLocaleString() : "Unknown Date";

    // Create new PDF document
    const doc = new jsPDF();
    
    // Add title
    doc.setFontSize(20);
    doc.setFont('helvetica', 'bold');
    doc.text('Exam Results Report', 105, 20, { align: 'center' });
    
    // Add student information
    doc.setFontSize(12);
    doc.setFont('helvetica', 'bold');
    doc.text('Student Information:', 20, 40);
    doc.setFont('helvetica', 'normal');
    doc.text(`Name: ${studentName}`, 20, 50);
    doc.text(`Email: ${result.user?.email || 'N/A'}`, 20, 60);
    doc.text(`ID: ${result.user?.randomId || 'N/A'}`, 20, 70);
    
    // Add exam information
    doc.setFont('helvetica', 'bold');
    doc.text('Exam Information:', 20, 90);
    doc.setFont('helvetica', 'normal');
    doc.text(`Exam: ${result.examTitle || 'Python Programming Assessment'}`, 20, 100);
    doc.text(`Date: ${examDate}`, 20, 110);
    doc.text(`Score: ${result.correctAnswers * 2}/40`, 20, 120);
    doc.text(`Status: ${passed ? 'Pass' : 'Fail'}`, 20, 130);
    
    // Add performance summary
    doc.setFont('helvetica', 'bold');
    doc.text('Performance Summary:', 20, 150);
    doc.setFont('helvetica', 'normal');
    doc.text(`Correct Answers: ${result.correctAnswers}/20`, 20, 160);
    doc.text(`Incorrect Answers: ${result.incorrectAnswers || (20 - result.correctAnswers)}/20`, 20, 170);
    doc.text(`Percentage: ${((result.correctAnswers / 20) * 100).toFixed(1)}%`, 20, 180);
    
    // Add question analysis (first 10 questions to fit on one page)
    doc.setFont('helvetica', 'bold');
    doc.text('Question Analysis (First 10):', 20, 200);
    doc.setFont('helvetica', 'normal');
    
    let yPos = 210;
    const questionsToShow = Math.min(10, result.questions.length);
    
    for (let i = 0; i < questionsToShow; i++) {
      const q = result.questions[i];
      const userAnswer = result.answers[i];
      const isCorrect = userAnswer === q.correct;
      
      if (yPos > 270) {
        doc.addPage();
        yPos = 20;
      }
      
      doc.setFontSize(10);
      doc.text(`Q${i + 1}: ${isCorrect ? 'Γ£ô' : 'Γ£ù'} ${userAnswer !== null ? String.fromCharCode(65 + userAnswer) : 'Not Attempted'}`, 20, yPos);
      yPos += 7;
    }
    
    // Add generation date
    doc.setFontSize(10);
    doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 105, 280, { align: 'center' });
    
    // Save the PDF
    doc.save(`exam-results-${studentName.replace(/\s+/g, '_')}.pdf`);
  };

  if (!result) {
    return (
      <div className="p-8 text-center">
        <h2 className="text-xl font-semibold">
          No Exam Results Found
        </h2>
        <button
          onClick={handleBack}
          className="mt-4 bg-blue-600 text-white px-4 py-2 rounded"
        >
          Back to Results
        </button>
      </div>
    );
  }

  const passed = (result.correctAnswers * 2) >= 20;

  return (

    <div className="p-6">

      {/* HEADER */}

      <div className="flex justify-between mb-6">

        <button
          onClick={handleBack}
          className="bg-gray-600 text-white px-4 py-2 rounded flex gap-2 items-center"
        >
          <FontAwesomeIcon icon={faArrowLeft} />
          Back
        </button>

        <button
          onClick={handleDownload}
          className="bg-gray-600 text-white px-4 py-2 rounded flex gap-2 items-center"
        >
          <FontAwesomeIcon icon={faDownload} />
          Download
        </button>

      </div>

      {/* STUDENT INFO */}

      <div className="bg-white shadow p-6 mb-6">

        <h2 className="text-xl font-bold mb-4">
          Student Information
        </h2>

        <div className="grid grid-cols-4 gap-4 text-center">

          <div>
            <h3 className="text-gray-600">Name</h3>
            <p className="font-bold text-blue-600">
              {result.user?.firstName || result.user?.username}
            </p>
          </div>

          <div>
            <h3 className="text-gray-600">ID</h3>
            <p className="font-bold text-blue-600">
              {result.user?.randomId}
            </p>
          </div>

          <div>
            <h3 className="text-gray-600">Score</h3>
            <p className="font-bold text-blue-600">
              {result.correctAnswers * 2}/40
            </p>
          </div>

          <div>
            <h3 className="text-gray-600">Status</h3>
            <p
              className={`font-bold ${
                passed ? "text-green-600" : "text-red-600"
              }`}
            >
              {passed ? "Pass" : "Fail"}
            </p>
          </div>

        </div>

      </div>

      {/* PERFORMANCE SUMMARY */}

      <div className="bg-white shadow p-6 mb-6">

        <h2 className="text-xl font-bold mb-4">
          Performance Summary
        </h2>

        <div className="grid grid-cols-3 gap-4 text-center">

          <div className="bg-green-50 p-4 rounded-lg">
            <h3 className="text-green-600 font-semibold">Correct</h3>
            <p className="text-2xl font-bold text-green-700">
              {result.correctAnswers}
            </p>
            <p className="text-sm text-green-600">
              {((result.correctAnswers / 20) * 100).toFixed(1)}%
            </p>
          </div>

          <div className="bg-red-50 p-4 rounded-lg">
            <h3 className="text-red-600 font-semibold">Wrong</h3>
            <p className="text-2xl font-bold text-red-700">
              {result.incorrectAnswers || (20 - result.correctAnswers)}
            </p>
            <p className="text-sm text-red-600">
              {(((result.incorrectAnswers || (20 - result.correctAnswers)) / 20) * 100).toFixed(1)}%
            </p>
          </div>

          <div className="bg-gray-50 p-4 rounded-lg">
            <h3 className="text-gray-600 font-semibold">Not Attempted</h3>
            <p className="text-2xl font-bold text-gray-700">
              {result.answers?.filter(a => a === null || a === undefined).length || 0}
            </p>
            <p className="text-sm text-gray-600">
              {((result.answers?.filter(a => a === null || a === undefined).length || 0) / 20 * 100).toFixed(1)}%
            </p>
          </div>

        </div>

      </div>

      {/* QUESTIONS - Show regardless of pass/fail score */}

      <div className="bg-white shadow p-6">

        <h2 className="text-xl font-bold mb-6">
          Detailed Question Analysis
        </h2>

        {/* Always show questions if data exists - regardless of score */}
        {result && result.questions && Array.isArray(result.questions) && result.questions.length > 0 ? (
          <div>
            {/* Info about performance */}
            <div className="mb-4 p-3 bg-blue-50 rounded">
              <p className="text-blue-700">
                Showing {result.questions.length} questions - Score: {result.correctAnswers || 0}/{result.totalQuestions || 20}
              </p>
            </div>

            {/* Map through all questions */}
            {result.questions.map((question, questionIndex) => {
              // Safe access to all data with fallbacks
              const questionText = question?.question || `Question ${questionIndex + 1}`;
              const options = Array.isArray(question?.options) ? question.options : [];
              const correctAnswerIndex = question?.correct ?? 0;
              const userAnswerIndex = Array.isArray(result?.answers) ? result.answers[questionIndex] : null;
              const isCorrect = userAnswerIndex === correctAnswerIndex;
              const notAttempted = userAnswerIndex === null || userAnswerIndex === undefined;
              
              return (
                <div key={questionIndex} className="border rounded-lg p-4 mb-4 bg-gray-50">
                  
                  {/* Question header with status */}
                  <div className="mb-3">
                    <h3 className="font-bold text-lg mb-2">
                      Question {questionIndex + 1}: {questionText}
                    </h3>
                    <div className={`inline-block px-3 py-1 rounded-full text-sm font-semibold ${
                      notAttempted 
                        ? 'bg-gray-100 text-gray-600' 
                        : isCorrect 
                          ? 'bg-green-100 text-green-800' 
                          : 'bg-red-100 text-red-800'
                    }`}>
                      {notAttempted ? 'Not Attempted' : isCorrect ? 'Correct' : 'Wrong'}
                    </div>
                  </div>

                  {/* Options display */}
                  <div className="space-y-2 mb-4">
                    {options.map((option, optionIndex) => {
                      const isSelected = userAnswerIndex === optionIndex;
                      const isCorrectOption = correctAnswerIndex === optionIndex;
                      
                      // Simple styling based on status
                      let bgColor = 'bg-white border-gray-300';
                      if (isSelected && isCorrectOption) {
                        bgColor = 'bg-green-100 border-green-500';
                      } else if (isSelected && !isCorrectOption) {
                        bgColor = 'bg-red-100 border-red-500';
                      } else if (isCorrectOption) {
                        bgColor = 'bg-green-50 border-green-300';
                      }
                      
                      return (
                        <div key={optionIndex} className={`p-3 rounded border-2 ${bgColor}`}>
                          <div className="flex justify-between items-center">
                            <span className="flex-1">
                              {String.fromCharCode(65 + optionIndex)}. {option}
                            </span>
                            <div className="flex gap-2 ml-4">
                              {isCorrectOption && (
                                <span className="text-green-600 font-semibold text-sm">
                                  Γ£ô Correct
                                </span>
                              )}
                              {isSelected && !isCorrectOption && (
                                <span className="text-red-600 font-semibold text-sm">
                                  Γ£ù Your Answer
                                </span>
                              )}
                              {isSelected && isCorrectOption && (
                                <span className="text-green-600 font-semibold text-sm">
                                  Γ£ô Your Answer
                                </span>
                              )}
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  {/* Answer summary */}
                  <div className="mt-4 pt-3 border-t border-gray-300">
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <span className="font-semibold text-gray-600">Your Answer: </span>
                        <span className={`font-semibold ${
                          notAttempted 
                            ? 'text-gray-500' 
                            : isCorrect 
                              ? 'text-green-600' 
                              : 'text-red-600'
                        }`}>
                          {notAttempted 
                            ? 'Not Attempted' 
                            : `${String.fromCharCode(65 + userAnswerIndex)}. ${options[userAnswerIndex]}`
                          }
                        </span>
                      </div>
                      <div>
                        <span className="font-semibold text-gray-600">Correct Answer: </span>
                        <span className="font-semibold text-green-600">
                          {String.fromCharCode(65 + correctAnswerIndex)}. {options[correctAnswerIndex]}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          /* No questions available */
          <div className="text-center py-8">
            <p className="text-gray-500">No questions available</p>
            <div className="mt-4 text-sm text-gray-400">
              <p>Result exists: {result ? 'Yes' : 'No'}</p>
              <p>Questions count: {result?.questions?.length || 0}</p>
              <p>Answers count: {result?.answers?.length || 0}</p>
            </div>
          </div>
        )}

      </div>

    </div>

  );

}

export default DetailedResults;

import React, { useState, useEffect } from "react";
import { motion } from "framer-motion";
import { toast } from "react-toastify";
import "bootstrap-icons/font/bootstrap-icons.css";

function ExamLeaderboard() {

  //  STATE
  const [leaderboard, setLeaderboard] = useState([]);
  const [date, setDate] = useState("");
  const [batch, setBatch] = useState("");
  const [examType, setExamType] = useState("");
  const [showRules, setShowRules] = useState(true);
  const [loading, setLoading] = useState(true);       // only true on first load
  const [isRefreshing, setIsRefreshing] = useState(false); // silent background refresh

  //  FETCH FUNCTION
  const fetchLeaderboard = async (isInitial = false) => {
    try {
      if (isInitial) setLoading(true);
      else setIsRefreshing(true);

      const params = new URLSearchParams();
      if (date) params.append('date', date);
      if (batch) params.append('batch', batch);
      if (examType) params.append('exam_type', examType);

      const res = await fetch(`http://127.0.0.1:8000/api/leaderboard/?${params.toString()}`);
      const data = await res.json();

      if (data.success) {
        setLeaderboard(data.data || []);
        // Only show toast on manual/initial load, not on every 15-sec refresh
        if (isInitial) toast.success("Leaderboard loaded", { toastId: "leaderboardToast" });
      } else {
        if (isInitial) toast.error("Failed to load leaderboard", { toastId: "leaderboardToast" });
      }
    } catch (error) {
      console.error(error);
      if (isInitial) toast.error("Failed to load leaderboard", { toastId: "leaderboardToast" });
    } finally {
      setLoading(false);
      setIsRefreshing(false);
    }
  };

  //  AUTO LOAD + SILENT AUTO REFRESH every 30 sec
  useEffect(() => {
    fetchLeaderboard(true); // initial load ΓÇö shows spinner + toast

    const interval = setInterval(() => fetchLeaderboard(false), 30000); // silent refresh
    return () => clearInterval(interval);
  }, [date, batch, examType]);

  //  SAFE PODIUM
  const first = leaderboard.find((s) => s.rank === 1) || {};
  const second = leaderboard.find((s) => s.rank === 2) || {};
  const third = leaderboard.find((s) => s.rank === 3) || {};

  // LOADING STATE
  if (loading) {
    return <p className="text-center mt-10">Loading leaderboard...</p>;
  }

  return (
    <div className="p-6 max-w-6xl mx-auto">

      {/* Rules Popup */}
      {showRules && (
        <div className="fixed inset-0 flex items-center justify-center bg-black/20 backdrop-blur-sm z-50">

          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md p-6">

            <div className="text-center mb-4">
              <h2 className="text-xl font-semibold">
                Leaderboard Ranking Rules
              </h2>
              <i className="bi bi-stopwatch-fill text-green-500 text-4xl mt-2"></i>
            </div>

            <div className="text-sm text-gray-700 space-y-3">

              <p><b>1. Primary Rank</b></p>
              <p>Higher score = Higher rank</p>

              <p><b>2. Tiebreakers</b></p>
              <ul className="list-disc ml-5">
                <li>Execution time</li>
                <li>Time spent</li>
                <li>Memory usage</li>
                <li>Questions solved</li>
              </ul>

              <p><b>3. Rank Score</b></p>
              <p>Top Rank = 1 | Mid Rank = 2 | Low Rank = 3</p>

            </div>

            <button
              onClick={() => setShowRules(false)}
              className="mt-5 w-full bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition"
            >
              OK
            </button>

          </div>

        </div>
      )}

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">

        <div>
          <label className="text-sm font-medium">Date</label>
          <input
            type="date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
            className="w-full border rounded-lg px-3 py-2 mt-1"
          />
        </div>

        <div>
          <label className="text-sm font-medium">Batch</label>
          <div className="w-full border rounded-lg px-3 py-2 mt-1 bg-gray-100 text-gray-500 cursor-not-allowed">
            All Batches
          </div>
        </div>

        <div>
          <label className="text-sm font-medium">Exam Type</label>
          <select
            value={examType}
            onChange={(e) => setExamType(e.target.value)}
            className="w-full border rounded-lg px-3 py-2 mt-1"
          >
            <option value="">Select</option>
            <option value="daily">Daily Exam</option>
            <option value="weekly">Weekly Exam</option>
            <option value="monthly">Monthly Exam</option>
            <option value="grand">Grand Test</option>
          </select>
        </div>

      </div>

      <h2 className="text-center text-2xl font-semibold mb-8">
        Leaderboard
      </h2>

      {/* Podium */}
      <div className="mt-6 flex justify-center items-end gap-10">

        {/* Rank 2 */}
        <motion.div
          initial={{ y: 60, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="flex flex-col items-center"
        >
          <div className="bg-blue-500 text-white rounded-xl w-32 h-36 flex items-center justify-center flex-col shadow-lg">
            <span className="text-3xl font-bold">2</span>
            <p className="text-sm font-semibold mt-1">{(second.username || "-").toUpperCase()}</p>
          </div>
        </motion.div>

        {/* Rank 1 */}
        <motion.div
          initial={{ y: 60, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="flex flex-col items-center"
        >
          <div className="bg-yellow-400 text-black rounded-xl w-36 h-48 flex items-center justify-center flex-col shadow-xl">
            <span className="text-4xl font-bold">1</span>
            <p className="text-sm font-semibold mt-1">{(first.username || "-").toUpperCase()}</p>
          </div>
        </motion.div>

        {/* Rank 3 */}
        <motion.div
          initial={{ y: 60, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          className="flex flex-col items-center"
        >
          <div className="bg-blue-500 text-white rounded-xl w-32 h-36 flex items-center justify-center flex-col shadow-lg">
            <span className="text-3xl font-bold">3</span>
            <p className="text-sm font-semibold mt-1">{(third.username || "-").toUpperCase()}</p>
          </div>
        </motion.div>

      </div>

      {/* Table */}
      <div className="mt-10 max-w-4xl mx-auto overflow-x-auto">

        <table className="w-full border-collapse rounded-lg shadow-md text-sm">

          <thead className="bg-gray-800 text-white">
            <tr>
              <th className="py-3 px-4 text-center">Rank</th>
              <th className="py-3 px-4 text-center">Name</th>
              <th className="py-3 px-4 text-center">Time</th>
              <th className="py-3 px-4 text-center">Score</th>
            </tr>
          </thead>

          <tbody>
            {leaderboard.length > 0 ? (
              leaderboard.map((student) => (
                <tr key={student.rank} className="border-t hover:bg-gray-50 transition-colors">
                  <td className="py-3 px-4 text-center font-semibold text-gray-700">{student.rank}</td>
                  <td className="py-3 px-4 text-center font-medium uppercase tracking-wide">{student.username}</td>
                  <td className="py-3 px-4 text-center text-gray-600">{student.time_taken}</td>
                  <td className="py-3 px-4 text-center font-bold text-indigo-700">{student.score}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="4" className="py-6 text-center text-gray-500">
                  No data available
                </td>
              </tr>
            )}
          </tbody>

        </table>

      </div>

    </div>
  );
}

export default ExamLeaderboard;

import { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

function ExamReportDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchDetail = async () => {
      try {
        const res = await axios.get(`http://127.0.0.1:8000/api/exam-report-detail/${id}/`);
        if (res.data && res.data.success) {
          const d = res.data.data;
          // Flatten: merge attempt fields with questions/answers/percentage/passed
          setReport({
            ...d.attempt,
            questions: d.questions || [],
            answers: d.answers || [],
            percentage: d.percentage || 0,
            passed: d.passed || false,
          });
        } else {
          setError("Report not found.");
        }
      } catch (err) {
        setError("Failed to load report.");
      } finally {
        setLoading(false);
      }
    };
    fetchDetail();
  }, [id]);

  if (loading) return (
    <div className="container mt-5 text-center">
      <div className="spinner-border text-primary" role="status" />
      <p className="mt-2 text-muted">Loading report...</p>
    </div>
  );
  if (error) return <div className="container mt-5 text-center text-danger">{error}</div>;
  if (!report) return null;

  const passed = report.passed;
  const percentage = report.percentage || 0;
  const questions = report.questions || [];
  const answers = report.answers || [];

  return (
    <div className="container mt-4 pb-5" style={{ maxWidth: "860px" }}>

      {/* Back Button */}
      <button
        className="btn btn-link text-secondary mb-3 ps-0"
        onClick={() => navigate(-1)}
      >
        ΓåÉ Back to Reports
      </button>

      {/* Summary Card */}
      <div className="card shadow-sm border-0 mb-4">
        <div className={`card-header fw-bold fs-5 text-white ${passed ? "bg-success" : "bg-danger"}`}>
          {report.exam_title || "Exam Report"} &nbsp;ΓÇö&nbsp; {passed ? "Γ£à PASS" : "Γ¥î FAIL"}
        </div>
        <div className="card-body">
          <div className="row text-center">
            <div className="col-md-3 col-6 mb-2">
              <h4 className="text-primary fw-bold mb-0">{report.marks_obtained ?? "ΓÇö"}/{report.total_marks ?? "ΓÇö"}</h4>
              <small className="text-muted">Score</small>
            </div>
            <div className="col-md-3 col-6 mb-2">
              <h4 className="text-success fw-bold mb-0">{report.correct_answers ?? "ΓÇö"}</h4>
              <small className="text-muted">Correct</small>
            </div>
            <div className="col-md-3 col-6 mb-2">
              <h4 className="text-danger fw-bold mb-0">{report.incorrect_answers ?? "ΓÇö"}</h4>
              <small className="text-muted">Wrong</small>
            </div>
            <div className="col-md-3 col-6 mb-2">
              <h4 className="fw-bold mb-0">{percentage}%</h4>
              <small className="text-muted">Percentage</small>
            </div>
          </div>

          <div className="progress mt-3" style={{ height: "14px", borderRadius: "7px" }}>
            <div
              className={`progress-bar ${passed ? "bg-success" : "bg-danger"}`}
              style={{ width: `${percentage}%`, borderRadius: "7px" }}
            />
          </div>

          <div className="d-flex justify-content-between mt-2 flex-wrap gap-1">
            <small className="text-muted">Student: <strong>{report.user?.username || report.user?.first_name || "Unknown"}</strong></small>
            <small className="text-muted">ID: <strong>{report.random_id || report.id || "N/A"}</strong></small>
            <small className="text-muted">Date: <strong>{report.exam_date ? new Date(report.exam_date).toLocaleDateString("en-GB") : "N/A"}</strong></small>
          </div>
        </div>
      </div>

      {/* Question Analysis */}
      {questions.length > 0 ? (
        <div>
          <h5 className="fw-bold mb-3">Question Analysis</h5>
          {questions.map((q, i) => {
            const userAnswer = answers[i];
            const correctKey = q.correct;
            const isCorrect = userAnswer === correctKey;
            const options = q.options || {};

            // Get display text for user answer and correct answer
            const getLetter = (idx) => isNaN(idx) ? idx : ["A","B","C","D"][parseInt(idx)] || idx;
            const userAnswerText = (userAnswer !== null && userAnswer !== undefined) 
              ? `${getLetter(userAnswer)}. ${options[userAnswer] || userAnswer}` 
              : "Not answered";
            const correctAnswerText = (correctKey !== null && correctKey !== undefined) 
              ? `${getLetter(correctKey)}. ${options[correctKey] || correctKey}` 
              : "N/A";

            return (
              <div
                key={i}
                className="card mb-4 border-0 shadow-sm"
                style={{ borderRadius: "12px", overflow: "hidden" }}
              >
                <div className="card-body pb-0">
                  {/* Question Header */}
                  <div className="mb-3">
                    <p className="fw-bold fs-6 mb-1">
                      Question {i + 1}: {q.question}
                    </p>
                    <span
                      className={`badge rounded-pill px-3 py-1`}
                      style={{
                        background: isCorrect ? "#d1fae5" : "#fee2e2",
                        color: isCorrect ? "#065f46" : "#991b1b",
                        fontSize: "0.75rem",
                        fontWeight: "600"
                      }}
                    >
                      {isCorrect ? "Γ£ô Correct" : "Γ£ù Wrong"}
                    </span>
                  </div>

                  {/* Options */}
                  <div>
                    {Object.entries(options).map(([key, value], optIdx) => {
                      // Handle both letter keys (A,B,C,D) and numeric keys (0,1,2,3)
                      const displayKey = isNaN(key) ? key : ["A","B","C","D"][parseInt(key)] || key;
                      const isThisCorrect = String(key) === String(correctKey) || displayKey === correctKey;
                      const isUserSelected = String(key) === String(userAnswer) || displayKey === userAnswer;
                      const isWrongSelection = isUserSelected && !isThisCorrect;

                      let bg = "#f9fafb";
                      let borderColor = "#e5e7eb";
                      let textColor = "#374151";

                      if (isThisCorrect && isUserSelected) {
                        bg = "#d1fae5";
                        borderColor = "#10b981";
                        textColor = "#065f46";
                      } else if (isWrongSelection) {
                        bg = "#fee2e2";
                        borderColor = "#ef4444";
                        textColor = "#991b1b";
                      } else if (isThisCorrect) {
                        bg = "#d1fae5";
                        borderColor = "#10b981";
                        textColor = "#065f46";
                      }

                      return (
                        <div
                          key={key}
                          className="d-flex justify-content-between align-items-center px-3 py-2 mb-2"
                          style={{
                            background: bg,
                            border: `1.5px solid ${borderColor}`,
                            borderRadius: "8px",
                            color: textColor,
                          }}
                        >
                          <span><strong>{displayKey}.</strong> {value}</span>
                          <span className="fw-semibold" style={{ fontSize: "0.85rem", whiteSpace: "nowrap" }}>
                            {isThisCorrect && isUserSelected && "Γ£ô Correct  Γ£ô Your Answer"}
                            {isWrongSelection && "Γ£ù Your Answer"}
                            {isThisCorrect && !isUserSelected && "Γ£ô Correct"}
                          </span>
                        </div>
                      );
                    })}
                  </div>

                  {/* Footer ΓÇö Your Answer / Correct Answer */}
                  <div
                    className="d-flex justify-content-between align-items-center mt-3 pt-2 pb-3"
                    style={{ borderTop: "1px solid #e5e7eb", fontSize: "0.9rem" }}
                  >
                    <span>
                      Your Answer:{" "}
                      <strong style={{ color: isCorrect ? "#10b981" : "#ef4444" }}>
                        {userAnswerText}
                      </strong>
                    </span>
                    <span>
                      Correct Answer:{" "}
                      <strong style={{ color: "#10b981" }}>{correctAnswerText}</strong>
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="text-center mt-4 text-muted">
          <p>No question data available for this report.</p>
          <small>Questions are only available for exams taken after the latest update.</small>
        </div>
      )}
    </div>
  );
}

export default ExamReportDetail;

