import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import Globe from "../components/Globe";

function Login() {

  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

const handleLogin = async () => {

  if (!username || !password) {
    toast.error("Please enter username and password");
    return;
  }

  if (loading) return;

  setLoading(true);
  setError("");

  try {

    const response = await fetch("http://127.0.0.1:8000/api/login/", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        username: username,
        password: password
      })
    });

    let data = {};
    try {
      data = await response.json();
      console.log("LOGIN RESPONSE:", data);
    } catch {
      data = {};
    }

    if (response.ok) {
      console.log("LOGIN RESPONSE:", data);

      localStorage.setItem("access", data.access);
      localStorage.setItem("refresh", data.refresh);
      console.log("Saved Token:", localStorage.getItem("access"));

      const randomId = Math.floor(1000 + Math.random() * 9000);

      const user = {
        username: username,
        id: randomId
      };

      localStorage.setItem("user", JSON.stringify(user));

      toast.success(`Welcome ${username}`);
      navigate("/dashboard",{replace:true});
      window.location.reload();
          

    } else {

      toast.error(data.detail || "Invalid username or password");

    }

  } catch (error) {

    toast.error("Server error. Please try again.");

  }

  setLoading(false);
};
  return (
    <div className="flex h-screen w-full overflow-hidden">

      {/* LEFT SIDE */}
      <div className="w-1/2 h-full bg-black relative flex items-center justify-center overflow-hidden">

        <Globe />

        <div className="absolute left-16 text-white z-10 max-w-md">

          <div className="flex items-center gap-2 mb-6">
            <span className="text-4xl font-bold">Hello</span>
            <div className="w-4 h-4 bg-green-500"></div>
          </div>

          <p className="text-gray-400 text-lg mb-2">
            Welcome to
          </p>

          <h1 className="text-5xl font-bold mb-4">
            Placement Portal
          </h1>

          <p className="text-gray-400">
            Practice coding, prepare for interviews and land your dream job.
          </p>

        </div>
      </div>

      {/* RIGHT SIDE */}

      <div className="w-1/2 h-full flex items-center justify-center bg-gray-100">

        <div className="bg-white shadow-2xl rounded-xl p-10 w-[420px]">

          <h1 className="text-3xl font-semibold mb-2">
            Welcome back!
          </h1>

          <p className="text-gray-500 mb-8">
            Login to your account
          </p>

          {/* USERNAME */}

          <input
            type="text"
            placeholder="Your username"
            value={username}
            onChange={(e)=>setUsername(e.target.value)}
            className="w-full border border-gray-300 rounded-lg px-4 py-3 mb-4 focus:outline-none focus:ring-2 focus:ring-green-500"
          />

          {/* PASSWORD */}

          <div className="relative mb-2">

            <input
              type={showPassword ? "text" : "password"}
              placeholder="Your password"
              value={password}
              onChange={(e)=>setPassword(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-4 py-3 pr-10 focus:outline-none focus:ring-2 focus:ring-green-500"
            />

            <button
              type="button"
              onClick={()=>setShowPassword(!showPassword)}
              className="absolute right-3 top-3"
            >
              ≡ƒæü
            </button>

          </div>

          {/* ERROR MESSAGE */}

          {error && (
            <p className="text-red-500 text-sm mb-4">
              {error}
            </p>
          )}

          {/* LOGIN BUTTON */}

          <button
            onClick={handleLogin}
            disabled={loading}
            className="w-full py-3 mb-4 rounded-lg font-semibold text-white bg-green-600 hover:bg-green-500 transition shadow-lg cursor-pointer"
          >
            {loading ? "Logging in..." : "Log In"}
          </button>
          <div className="flex justify-between text-sm mb-6">
            <label className="flex items-center gap-2">
              <input type="checkbox" />
              Remember me
            </label>

            <a href="#" className="text-blue-600">
              Forgot password?
            </a>

          </div>

        </div>

      </div>

    </div>
  );
}

export default Login;

import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faClock,
  faUser,
  faCircle,
  faFlag,
  faArrowRight,
  faCamera,
} from "@fortawesome/free-solid-svg-icons";

// Indestructible global array to catch all streams outside React DOM scope
let globalStreamsToClean = [];

const MonthlyExam = () => {
  const navigate = useNavigate();
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const faceDetectionIntervalRef = useRef(null);
  const violationStartTimeRef = useRef(null);
  const cleanTimeoutRef = useRef(null);

  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState(new Array(20).fill(null));
  const [markedForReview, setMarkedForReview] = useState(new Array(20).fill(false));
  const [visitedQuestions, setVisitedQuestions] = useState(new Array(20).fill(false));

  const [timeLeft, setTimeLeft] = useState(2700);
  const [examStarted, setExamStarted] = useState(false);
  const [examSubmitted, setExamSubmitted] = useState(false);
  const examSubmittedRef = useRef(false);
  const [webcamActive, setWebcamActive] = useState(false);
  const [faceCount, setFaceCount] = useState(0);
  const [examFailed, setExamFailed] = useState(false);

  const [questions, setQuestions] = useState([]);
  const [isLoadingQuestions, setIsLoadingQuestions] = useState(true);

  // Fetch 20 randomized questions from the backend pool
  useEffect(() => {
    const fetchQuestionsFromBackend = async () => {
      const savedStateStr = sessionStorage.getItem('monthlyExamState');
      if (savedStateStr) {
        try {
          const savedState = JSON.parse(savedStateStr);
          if (savedState.questions && savedState.questions.length > 0 && savedState.examStarted && !savedState.examSubmitted) {
            setQuestions(savedState.questions);
            setIsLoadingQuestions(false);
            return;
          }
        } catch (e) {}
      }

      try {
        setIsLoadingQuestions(true);
        const res = await fetch("http://127.0.0.1:8000/api/playground-questions/");
        const json = await res.json();

        if (json.success && json.data && json.data.length > 0) {
          const mappedQuestions = json.data.map((q, idx) => ({ ...q, id: idx + 1 }));
          setQuestions(mappedQuestions);
        }
      } catch (err) {
        console.error("Failed to fetch questions from backend:", err);
      } finally {
        setIsLoadingQuestions(false);
      }
    };

    fetchQuestionsFromBackend();
  }, []);

  // Load state from sessionStorage if it exists
  useEffect(() => {
    const savedStateStr = sessionStorage.getItem('monthlyExamState');
    if (savedStateStr) {
      try {
        const savedState = JSON.parse(savedStateStr);
        if (savedState.examStarted && !savedState.examSubmitted) {
          setAnswers(savedState.answers);
          setMarkedForReview(savedState.markedForReview);
          setVisitedQuestions(savedState.visitedQuestions);
          setTimeLeft(savedState.timeLeft);
          setCurrentQuestion(savedState.currentQuestion);
          setExamStarted(true);
          examSubmittedRef.current = false;
          // Resume webcam if not already active
          setTimeout(() => {
            if (videoRef.current && !webcamActive) {
              startWebcam();
            }
          }, 500);
        }
      } catch (e) {}
    }
  }, []);

  // Sync state to sessionStorage whenever it changes
  useEffect(() => {
    if (examStarted && !examSubmitted && questions.length > 0) {
      const stateToSave = {
        questions,
        answers,
        markedForReview,
        visitedQuestions,
        timeLeft,
        currentQuestion,
        examStarted,
        examSubmitted
      };
      sessionStorage.setItem('monthlyExamState', JSON.stringify(stateToSave));
    }
  }, [answers, markedForReview, visitedQuestions, timeLeft, currentQuestion, examStarted, examSubmitted, questions]);

  // TIMER
  useEffect(() => {
    if (examStarted && !examSubmitted && timeLeft > 0) {
      const timer = setTimeout(() => setTimeLeft(timeLeft - 1), 1000);
      return () => clearTimeout(timer);
    }
    if (timeLeft === 0 && !examSubmitted) handleSubmitExam();
  }, [timeLeft, examStarted, examSubmitted]);

  // Turn off webcam when component unmounts (page closed)
  useEffect(() => {
    return () => {
      stopWebcam();
    };
  }, []);

  // Prevent back button
  useEffect(() => {
    if (examStarted && !examSubmitted) {
      window.history.pushState(null, null, window.location.href);
      const handlePopState = (e) => {
        window.history.pushState(null, null, window.location.href);
      };
      window.addEventListener('popstate', handlePopState);
      return () => window.removeEventListener('popstate', handlePopState);
    }
  }, [examStarted, examSubmitted]);

  // WEBCAM FUNCTIONS
  const startWebcam = async () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 320 }, height: { ideal: 240 } },
        audio: false // No audio capture
      });

      globalStreamsToClean.push(stream);

      // Stop stream immediately if the exam was already submitted or window unmounted
      if (examSubmittedRef.current || !videoRef.current) {
        stopWebcam();
        return;
      }

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
        setWebcamActive(true);
        startFaceDetection();
      }
    } catch (err) {
      console.error("Error accessing webcam:", err);
      alert("Unable to access webcam. Please ensure camera permissions are granted.");
    }
  };

  const stopWebcam = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    globalStreamsToClean.forEach(s => {
      s.getTracks().forEach(track => track.stop());
    });
    globalStreamsToClean = []; // reset
    setWebcamActive(false);

    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    if (faceDetectionIntervalRef.current) {
      clearInterval(faceDetectionIntervalRef.current);
      faceDetectionIntervalRef.current = null;
    }
    if (cleanTimeoutRef.current) {
      clearTimeout(cleanTimeoutRef.current);
      cleanTimeoutRef.current = null;
    }
    violationStartTimeRef.current = null;
  };

  const startFaceDetection = () => {
    faceDetectionIntervalRef.current = setInterval(() => {
      if (!videoRef.current || !examStarted || examSubmitted) return;
      const video = videoRef.current;
      if (video.videoWidth === 0 || video.videoHeight === 0) return;

      const canvas = document.createElement("canvas");
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;

      let rTotal = 0, gTotal = 0, bTotal = 0;
      let maxAdjacentDiff = 0;

      for (let i = 0; i < data.length - 4; i += 4) {
        const r = data[i], g = data[i+1], b = data[i+2];
        rTotal += r; gTotal += g; bTotal += b;

        // Prevent false edge-jumps by skipping the right-most pixel wrapping around to the left
        if (((i / 4) + 1) % canvas.width === 0) continue;

        // Calculate absolute contrast jump between this pixel and the immediate next pixel
        const diff = Math.abs(r - data[i+4]) + Math.abs(g - data[i+5]) + Math.abs(b - data[i+6]);
        if (diff > maxAdjacentDiff) {
            maxAdjacentDiff = diff;
        }
      }

      const pixelCount = canvas.width * canvas.height;
      const avgBrightness = (0.299 * (rTotal/pixelCount) + 0.587 * (gTotal/pixelCount) + 0.114 * (bTotal/pixelCount));

      const isDark = avgBrightness < 40;
      const isRedDominant = (rTotal > gTotal * 2) && (rTotal > bTotal * 2);

      // If the absolutely sharpest edge in the entire video feed is extremely weak (< 85 combined RGB difference),
      // the video is definitively blurred out by Software (e.g., OBS Gaussian Blur) or physically blocked by an object at 0mm focal depth.
      // Normal human features (like eyes, hair, teeth) create native pixel jumps well over 150+.
      const isBlurred = maxAdjacentDiff < 85;

      const checkViolations = (faces) => {
        const isCameraCovered = isDark || isBlurred || isRedDominant;
        const isMultipleFaces = faces && faces.length > 1;

        if (isCameraCovered || isMultipleFaces) {
          if (cleanTimeoutRef.current) {
            clearTimeout(cleanTimeoutRef.current);
            cleanTimeoutRef.current = null;
          }
          if (!violationStartTimeRef.current) {
            console.log("≡ƒÜ¿ SECURITY VIOLATION WARNING: Condition active, waiting 2 seconds...");
            violationStartTimeRef.current = Date.now();
          } else if (Date.now() - violationStartTimeRef.current >= 2000) {
            handleSubmitExam(isCameraCovered ? "Camera covered or blocked" : "Multiple faces detected on webcam");
          }
        } else {
          if (violationStartTimeRef.current && !cleanTimeoutRef.current) {
            cleanTimeoutRef.current = setTimeout(() => {
              violationStartTimeRef.current = null;
              cleanTimeoutRef.current = null;
            }, 1000); // Require clean picture for 1s to forgive
          }
        }
      };

      // Face Detection using native Shape Detection API if available
      if (window.FaceDetector) {
        const faceDetector = new window.FaceDetector({ maxDetectedFaces: 5 });
        faceDetector.detect(canvas)
          .then(faces => {
            setFaceCount(faces.length);
            checkViolations(faces);
          })
          .catch(err => {
            console.error(err);
            checkViolations(null);
          });
      } else {
        setFaceCount(1);
        checkViolations(null);
      }
    }, 500);
  };

  const startExam = () => {
    setExamStarted(true);
    startWebcam();
  };

  const handleAnswerSelect = (qIndex, optionIndex) => {
    const newAnswers = [...answers];
    newAnswers[qIndex] = optionIndex;
    setAnswers(newAnswers);
  };

  const toggleMarkForReview = (index) => {
    const updated = [...markedForReview];
    updated[index] = !updated[index];
    setMarkedForReview(updated);
  };

  const goToQuestion = (index) => {
    const visited = [...visitedQuestions];
    visited[index] = true;
    setVisitedQuestions(visited);
    setCurrentQuestion(index);
  };

  const nextQuestion = () => {
    if (currentQuestion < questions.length - 1) {
      goToQuestion(currentQuestion + 1);
    }
  };

  const previousQuestion = () => {
    if (currentQuestion > 0) {
      goToQuestion(currentQuestion - 1);
    }
  };

  // SUBMIT EXAM
  const handleSubmitExam = async (reason = "Manual submission") => {
    if (!examSubmittedRef.current) {
      setExamSubmitted(true);
      examSubmittedRef.current = true;
      stopWebcam(); // Stop webcam when submitting
    }

    const userStr = localStorage.getItem("user");
    let user = {};
    try {
      user = userStr && userStr !== "undefined" ? JSON.parse(userStr) : {};
    } catch(e) {
      console.error(e);
    }
    const randomId = Math.floor(1000 + Math.random() * 9000);

    let correctCount = 0;

    answers.forEach((ans, index) => {
      if (ans === questions[index].correct) correctCount++;
    });

    const result = {
      status: "completed",
      correctAnswers: correctCount,
      incorrectAnswers: 20 - correctCount,
      totalQuestions: 20,
      score: correctCount * 2,
      marks: correctCount * 2,
      totalMarks: 40,
      answers: answers,
      questions: questions,
      timeTaken: 2700 - timeLeft,
      user: {
        username: user.username || "Unknown",
        email: user.email || "",
        firstName: user.firstName || user.username,
        randomId: randomId
      },
      examDate: new Date().toISOString(),
      examTitle: "Monthly Python Programming Assessment",
      examType: "monthly"
    };

    const now = new Date().toISOString();
    const payload = {
      username: user.username || "Unknown",
      exam_title: "Monthly Python Programming Assessment",
      exam_type: "monthly",
      score: correctCount * 2,
      total_questions: 20,
      correct_answers: correctCount,
      incorrect_answers: 20 - correctCount,
      marks_obtained: correctCount * 2,
      total_marks: 40,
      time_taken: 2700 - timeLeft,
      start_time: now,
      end_time: now,
      status: "completed",
      random_id: String(randomId),
      answers: answers,
      questions: questions
    };

    try {
      const res = await fetch("http://127.0.0.1:8000/api/save-exam-report/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
        const errData = await res.json().catch(() => ({}));
        console.error("Save exam report failed:", res.status, errData);
      } else {
        const saved = await res.json().catch(() => ({}));
        console.log("Γ£à Exam saved for user:", saved.saved_username);
      }
    } catch (err) {
      console.error("Failed to sync exam to backend:", err);
    }

    const allResults = JSON.parse(localStorage.getItem("allExamResults") || "[]");
    allResults.unshift(result);
    localStorage.setItem("allExamResults", JSON.stringify(allResults));
    localStorage.setItem("examResult", JSON.stringify(result));

    sessionStorage.removeItem('monthlyExamState');

    navigate("/dashboard/playground-results",{replace:true});
  };

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, "0")}`;
  };

  if (!examStarted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="bg-white p-8 rounded-xl shadow-lg max-w-md w-full text-center">
          <FontAwesomeIcon icon={faCamera} className="text-4xl text-indigo-600 mb-4"/>
          <h2 className="text-2xl font-bold mb-2">
            Monthly Python Programming Exam
          </h2>
          <p className="text-gray-600 mb-6">
            20 Questions ΓÇó 45 Minutes
          </p>
          <button
            onClick={startExam}
            disabled={isLoadingQuestions}
            className={`px-6 py-3 rounded-lg text-white font-semibold transition-all ${
              isLoadingQuestions ? 'bg-gray-400 cursor-not-allowed animate-pulse' : 'bg-indigo-600 hover:bg-indigo-700 shadow-md'
            }`}
          >
            {isLoadingQuestions ? 'Fetching Assessment Paper...' : 'Start Exam'}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6 relative">
      {/* Webcam at Top Left */}
      <div className="fixed top-4 left-4 z-50 bg-white rounded-lg shadow-lg p-2">
        <div className="relative">
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="w-48 h-36 rounded border-2 border-gray-300"
            style={{ transform: 'scaleX(-1)' }}
          />
          {!webcamActive && (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-200 rounded">
              <FontAwesomeIcon icon={faCamera} className="text-gray-400 text-2xl" />
            </div>
          )}
          <div className="absolute top-1 right-1">
            <div className={`w-3 h-3 rounded-full ${webcamActive ? 'bg-green-500' : 'bg-red-500'} animate-pulse`}></div>
          </div>
        </div>
        <div className="text-xs text-center mt-1">
          {webcamActive ? 'Recording' : 'Inactive'}
        </div>
      </div>

      <div className="max-w-6xl mx-auto">
        <div className="bg-white p-4 rounded shadow flex justify-between mb-4">
          <div className="flex items-center gap-2">
            <FontAwesomeIcon icon={faClock}/>
            {formatTime(timeLeft)}
          </div>
          <div>
            Question {currentQuestion + 1} / {questions.length}
          </div>
        </div>

        <div className="grid grid-cols-4 gap-4">
          <div className="col-span-3 bg-white p-6 rounded shadow">
            <h3 className="font-semibold mb-4">
              Q{currentQuestion + 1}: {questions[currentQuestion].question}
            </h3>
            {questions[currentQuestion].options.map((option, index) => (
              <label key={index} className="block border p-3 rounded mb-3 cursor-pointer">
                <input
                  type="radio"
                  name={`q-${currentQuestion}`}
                  checked={answers[currentQuestion] === index}
                  onChange={() => handleAnswerSelect(currentQuestion, index)}
                  className="mr-2"
                />
                {option}
              </label>
            ))}
            <div className="flex justify-between mt-6">
              <button
                onClick={() => toggleMarkForReview(currentQuestion)}
                className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
              >
                Mark for Review
              </button>
              <div className="flex gap-2">
                {currentQuestion > 0 && (
                  <button
                    onClick={previousQuestion}
                    className="bg-gray-500 text-white px-4 py-2 rounded hover:bg-gray-600"
                  >
                    Previous
                  </button>
                )}
                {currentQuestion === questions.length - 1 ? (
                  <button
                    onClick={() => handleSubmitExam("Manual submission")}
                    className="bg-green-600 text-white px-6 py-2 rounded hover:bg-green-700"
                  >
                    Submit Exam
                  </button>
                ) : (
                  <button
                    onClick={nextQuestion}
                    className="bg-indigo-600 text-white px-6 py-2 rounded hover:bg-indigo-700"
                  >
                    Next
                  </button>
                )}
              </div>
            </div>
          </div>

          <div className="bg-white p-4 rounded shadow">
            <h4 className="font-semibold mb-3">Questions</h4>
            <div className="grid grid-cols-5 gap-2">
              {questions.map((_, index) => {
                let buttonClass = "p-2 rounded text-sm font-semibold ";

                if (markedForReview[index]) {
                  buttonClass += "bg-violet-500 text-white hover:bg-violet-600";
                } else if (answers[index] !== null) {
                  buttonClass += "bg-green-500 text-white hover:bg-green-600";
                } else if (visitedQuestions[index]) {
                  buttonClass += "bg-red-500 text-white hover:bg-red-600";
                } else {
                  buttonClass += "bg-gray-200 text-gray-700 hover:bg-gray-300";
                }

                return (
                  <button
                    key={index}
                    onClick={() => goToQuestion(index)}
                    className={buttonClass}
                  >
                    {index + 1}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MonthlyExam;

import { CircularProgressbar, buildStyles } from "react-circular-progressbar";
import "react-circular-progressbar/dist/styles.css";
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";

function MonthlyExamReports() {

  const [exams, setExams] = useState([]);
  const [progress, setProgress] = useState({});
  const navigate = useNavigate();

  //  FETCH DATA FROM BACKEND - Monthly exams only (this month)
  const fetchReports = async () => {
    try {
      const token = localStorage.getItem("access");

      const res = await axios.get("http://127.0.0.1:8000/api/monthly-exam-results/", {
        headers: token ? { Authorization: `Bearer ${token}` } : {}
      });

      let examList = [];
      if (res.data && Array.isArray(res.data.data)) {
        examList = res.data.data;
      } else if (Array.isArray(res.data)) {
        examList = res.data;
      }

      // Filter by logged-in user (case-insensitive)
      try {
        const userStr = localStorage.getItem("user");
        if (userStr && userStr !== "undefined") {
          const parsedUser = JSON.parse(userStr);
          const currentUsername = parsedUser?.username?.toLowerCase();
          if (currentUsername) {
            examList = examList.filter(
              (e) => e.user?.username?.toLowerCase() === currentUsername
            );
          }
        }
      } catch (e) {
        console.error("User parse error:", e);
      }

      // No fallback ΓÇö monthly page only shows monthly data
      setExams(examList);

    } catch (err) {
      console.error("Failed to fetch monthly exam reports:", err);
      setExams([]);
    }
  };

  useEffect(() => {
    fetchReports();
  }, []);

  //  ANIMATION AFTER DATA LOAD
  useEffect(() => {
    if (!Array.isArray(exams) || exams.length === 0) return;

    exams.forEach((exam) => {
      const total = exam.totalMarks || 40;
      const percentage = total > 0 ? (exam.score / total) * 100 : 0;

      let value = 0;
      const interval = setInterval(() => {
        value += 2;
        if (value >= percentage) {
          value = percentage;
          clearInterval(interval);
        }
        setProgress((prev) => ({
          ...prev,
          [exam.id]: value,
        }));
      }, 20);
    });

  }, [exams]);

  //  COLOR LOGIC
  const getColor = (percentage) => {
    if (percentage >= 80) return "#198754";
    if (percentage >= 60) return "#ffc107";
    return "#dc3545";
  };

  return (
    <div className="container mt-4">

      {/* BACK BUTTON */}
      <button
        onClick={() => navigate("/dashboard/exam-reports")}
        className="text-sm text-gray-600 hover:text-blue-600"
      >
        ΓåÉ Back
      </button>

      <div className="d-flex justify-content-between align-items-center mt-3 mb-4">
        <h3 className="mb-0 text-dark font-weight-bold">Monthly Exam Reports</h3>
        <span className="badge bg-primary fs-6 py-2 px-3 shadow-sm rounded-pill text-white">
          Total Exams Written: {exams.length}
        </span>
      </div>

      <div className="row mt-3">

        {exams.length > 0 ? (
          exams.map((exam) => {
            const total = exam.totalMarks || 40;
            const percentage = total > 0 ? (exam.score / total) * 100 : 0;
            const value = progress[exam.id] || 0;
            const color = getColor(percentage);

            return (
              <div className="col-md-3 mb-4" key={exam.id}>
                <div className="card text-center shadow-sm p-3">

                  <h6 className="mb-1 fw-bold text-truncate">
                    {exam.examTitle || `Exam-${exam.id}`}
                  </h6>

                  <small className="text-muted mb-2">
                    {exam.user?.username || "Unknown"}
                  </small>

                  <div style={{ width: "90px", margin: "auto" }}>
                    <CircularProgressbar
                      value={value}
                      text={`${Math.round(value)}%`}
                      styles={buildStyles({
                        pathColor: color,
                        textColor: color,
                        trailColor: "#e5e7eb",
                      })}
                    />
                  </div>

                  <p className="mt-3 text-muted mb-1">
                    Score: <strong>{exam.score}/{total}</strong>
                  </p>

                  <small className="text-muted">
                    {exam.examDate ? new Date(exam.examDate).toLocaleDateString() : ""}
                  </small>

                  <button
                    className="btn btn-primary btn-sm mt-2"
                    onClick={() =>
                      navigate(`/dashboard/exam-report-detail/${exam.id}`)
                    }
                  >
                    VIEW REPORT
                  </button>

                </div>
              </div>
            );
          })
        ) : (
          <div className="text-center mt-5">
            <p className="text-muted fs-5">No monthly exam reports found.</p>
            <p className="text-muted">Complete a Monthly Exam to see your results here!</p>
          </div>
        )}

      </div>

    </div>
  );
}

export default MonthlyExamReports;

